import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.Dh1jimFm.js";const p=JSON.parse('{"title":"QuickLauncher","description":"","frontmatter":{},"headers":[],"relativePath":"ai-translation/quicklauncher.md","filePath":"ai-translation/quicklauncher.md"}'),n={name:"ai-translation/quicklauncher.md"};function i(s,t,l,u,c,h){return a(),r("div",null,t[0]||(t[0]=[o('<h1 id="quicklauncher" tabindex="-1">QuickLauncher <a class="header-anchor" href="#quicklauncher" aria-label="Permalink to &quot;QuickLauncher&quot;">​</a></h1><p>The <strong>Supervertaler QuickLauncher</strong> is a floating AI action menu that gives you instant access to translation tools, the Supervertaler Assistant, and your custom prompts — without leaving your current workflow.</p><h2 id="opening-quicklauncher" tabindex="-1">Opening QuickLauncher <a class="header-anchor" href="#opening-quicklauncher" aria-label="Permalink to &quot;Opening QuickLauncher&quot;">​</a></h2><p>There are several ways to open the QuickLauncher:</p><h3 id="inside-supervertaler" tabindex="-1">Inside Supervertaler <a class="header-anchor" href="#inside-supervertaler" aria-label="Permalink to &quot;Inside Supervertaler&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>How</th></tr></thead><tbody><tr><td><strong>Right-click</strong> a source or target cell</td><td>Select text → right-click → <strong>⚡ QuickLauncher</strong></td></tr><tr><td><strong>Alt+K</strong> keyboard shortcut</td><td>Place your cursor in a cell → press <code>Alt+K</code></td></tr></tbody></table><p>The selected text in the cell is automatically used as input.</p><h3 id="from-any-external-application" tabindex="-1">From any external application <a class="header-anchor" href="#from-any-external-application" aria-label="Permalink to &quot;From any external application&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>How</th></tr></thead><tbody><tr><td><strong>Ctrl+Alt+K</strong> global hotkey</td><td>Select text in any app (Word, memoQ, Trados, browser, etc.) → press <code>Ctrl+Alt+K</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The global hotkey requires AutoHotkey to be installed. Supervertaler captures the selected text from your clipboard and opens the QuickLauncher.</p></div><h2 id="menu-items" tabindex="-1">Menu Items <a class="header-anchor" href="#menu-items" aria-label="Permalink to &quot;Menu Items&quot;">​</a></h2><p>When you open the QuickLauncher, you see a popup menu with the following items:</p><h3 id="quicktrans" tabindex="-1">QuickTrans <a class="header-anchor" href="#quicktrans" aria-label="Permalink to &quot;QuickTrans&quot;">​</a></h3><p><strong>⚡ QuickTrans</strong> opens a compact popup window that instantly translates the selected text using your configured AI provider.</p><ul><li>Press <code>Ctrl+M</code> to open QuickTrans directly (without the menu)</li><li>The translation appears in a floating popup</li><li>Useful for quick lookups while working in the grid</li></ul><p>See also: <a href="./single-segment.html">Single Segment Translation</a></p><h3 id="supervertaler-assistant" tabindex="-1">Supervertaler Assistant <a class="header-anchor" href="#supervertaler-assistant" aria-label="Permalink to &quot;Supervertaler Assistant&quot;">​</a></h3><p><strong>💬 Supervertaler Assistant</strong> opens a conversational AI chat inside the AI tab. Unlike one-shot translations, you can have a back-and-forth conversation:</p><ul><li>Ask follow-up questions (&quot;Can you rephrase this more formally?&quot;)</li><li>Get explanations (&quot;What does this legal term mean?&quot;)</li><li>Iterate on translations (&quot;Now adapt it for patents&quot;)</li></ul><p>The selected text is automatically inserted as your first message.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When launched from an external app via <code>Ctrl+Alt+K</code>, press <strong>Escape</strong> in the Assistant to return focus to the app you were working in.</p></div><h3 id="custom-prompts" tabindex="-1">Custom Prompts <a class="header-anchor" href="#custom-prompts" aria-label="Permalink to &quot;Custom Prompts&quot;">​</a></h3><p>Below the built-in items, you&#39;ll see any prompts you&#39;ve added to the QuickLauncher from the <a href="./prompt-library.html">Prompt Manager</a>.</p><p>Each prompt offers two actions:</p><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>▶ Run (show response)…</strong></td><td>Runs the prompt and shows the result in a dialog</td></tr><tr><td><strong>↺ Run and replace target selection</strong></td><td>Runs the prompt and replaces the selected text with the result</td></tr></tbody></table><p>When using the QuickLauncher from an external app (<code>Ctrl+Alt+K</code>), the second action becomes <strong>↺ Run and paste into app</strong> — the result is copied to your clipboard and pasted back into the external application.</p><h2 id="adding-prompts-to-quicklauncher" tabindex="-1">Adding Prompts to QuickLauncher <a class="header-anchor" href="#adding-prompts-to-quicklauncher" aria-label="Permalink to &quot;Adding Prompts to QuickLauncher&quot;">​</a></h2><ol><li>Go to the <strong>✨ AI</strong> tab → <strong>📋 Prompt Manager</strong></li><li>Create or select a prompt</li><li>Enable the <strong>Show in QuickLauncher</strong> option for that prompt</li></ol><p>Your prompt will then appear in the QuickLauncher menu every time you open it.</p><h2 id="context-and-variables" tabindex="-1">Context and Variables <a class="header-anchor" href="#context-and-variables" aria-label="Permalink to &quot;Context and Variables&quot;">​</a></h2><p>When a prompt runs from the QuickLauncher, it has access to the following context variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>{source_text}</code></td><td>The selected / captured text</td></tr><tr><td><code>{target_text}</code></td><td>The current segment&#39;s target text (in-grid only)</td></tr><tr><td><code>{source_lang}</code></td><td>Project source language</td></tr><tr><td><code>{target_lang}</code></td><td>Project target language</td></tr></tbody></table><p>This means your prompts can be language-aware and context-sensitive. For example, a prompt like <em>&quot;Explain {source_text} in simple {target_lang}&quot;</em> will automatically use the correct languages.</p><p>See <a href="./prompts.html">Creating Prompts</a> and <a href="./prompt-library.html">Prompt Manager</a> for more on writing and managing prompts.</p><h2 id="customizing-hotkeys" tabindex="-1">Customizing Hotkeys <a class="header-anchor" href="#customizing-hotkeys" aria-label="Permalink to &quot;Customizing Hotkeys&quot;">​</a></h2><p>You can change the default keyboard shortcuts for the QuickLauncher and QuickTrans in <strong>Settings → Keyboard Shortcuts</strong>.</p><table tabindex="0"><thead><tr><th>Default shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Alt+K</code></td><td>Open QuickLauncher (in-app)</td></tr><tr><td><code>Ctrl+Alt+K</code></td><td>Open QuickLauncher (global, from any app)</td></tr><tr><td><code>Ctrl+M</code></td><td>QuickTrans (direct, skip menu)</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Start with QuickTrans</strong> if you just need a quick translation — it&#39;s the fastest path.</li><li><strong>Use the Supervertaler Assistant</strong> when you need to discuss or iterate on a translation.</li><li><strong>Create custom prompts</strong> for repetitive tasks (e.g., &quot;Simplify this&quot;, &quot;Make formal&quot;, &quot;Extract terminology&quot;).</li><li>The QuickLauncher works without a project open — useful for general-purpose AI lookups.</li></ul><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./single-segment.html">Single Segment Translation</a></li><li><a href="./prompts.html">Creating Prompts</a></li><li><a href="./prompt-library.html">Prompt Manager</a></li><li><a href="./../editor/keyboard-shortcuts.html">Keyboard Shortcuts</a></li></ul>',42)]))}const m=e(n,[["render",i]]);export{p as __pageData,m as default};
